        [TestCaseSource(nameof(NativeCases))]
        public void MatchesOriginalPowerAndRandomState(string variant, int multiplier, int firstDamage,
            int secondDamage, uint seed, int expected, uint finalState)
        {
            var random = new BattleRandom(unchecked((int)seed));
            var rules = new BattleCoAttackRules(variant);
            var visited = new List<int>();
            int power = rules.Power(new[] { 101, 102, 0, 0 }, id =>
            {
                visited.Add(id);
                return id == 101 ? firstDamage : secondDamage;
            }, multiplier, random);
            Assert.That(power, Is.EqualTo(expected));
            Assert.That(random.State, Is.EqualTo(finalState));
            Assert.That(visited, Is.EqualTo(new[] { 101, 102 }));
        }

        [TestCase("PAL3", 0)]
        [TestCase("PAL3A", 12)]
        public void ZeroValuesFollowThePublishedLoop(string variant, int expectedCount)
        {
            var rules = new BattleCoAttackRules(variant);
            Assert.That(rules.EvaluationIndices(new int[12]).Count, Is.EqualTo(expectedCount));
            Assert.That(Enumerable.Range(0, 12).Where(BattleCoAttackRules.WritesResource), Is.EqualTo(new[] { 0, 1, 2 }));
            Assert.That(BattleCoAttackRules.SignedPower(-151, 0), Is.EqualTo(-151));
            Assert.That(BattleCoAttackRules.SignedPower(-151, 1), Is.EqualTo(151));
        }
    }
